Lemma gso_0RB1LC_1LC0RD_0LD0LA_1LA1RD : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_0RB1LC_1LC0RD_0LD0LA_1LA1RD.
Proof.
  intros p j E. destruct (Alph_10_11_11.cview_none_Alph_10_11_11 p j E) as (H1 & _).
