Lemma lbl_0RB1LC_1LC0RD_0LD0LA_1LA1RD : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_0RB1LC_1LC0RD_0LD0LA_1LA1RD : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_0RB1LC_1LC0RD_0LD0LA_1LA1RD) = lift (Cc (Pos.succ p)).
