Proof. exact lapi_0RB1LC_1LC0RD_0LD0LA_1LA1RD. Qed.

(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_0RB1LC_1LC0RD_0LD0LA_1LA1RD : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_0RB1LC_1LC0RD_0LD0LA_1LA1RD p (pow2 j)).
  - exists (4 * j + 13), (cden [] [] j BB1_0RB1LC_1LC0RD_0LD0LA_1LA1RD).
    split; [lia|]. split; [| exact (gbo_0RB1LC_1LC0RD_0LD0LA_1LA1RD j)].
    rewrite (gso_0RB1LC_1LC0RD_0LD0LA_1LA1RD p j E).
    exact (srun_sound tm true true chb_0RB1LC_1LC0RD_0LD0LA_1LA1RD B0_0RB1LC_1LC0RD_0LD0LA_1LA1RD BB1_0RB1LC_1LC0RD_0LD0LA_1LA1RD 4 13
             run_boot_0RB1LC_1LC0RD_0LD0LA_1LA1RD [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (4 * j + 15), (cden [] [] j B1_0RB1LC_1LC0RD_0LD0LA_1LA1RD).
    split; [| exact (geo_0RB1LC_1LC0RD_0LD0LA_1LA1RD p j E)].
    rewrite (gxi_0RB1LC_1LC0RD_0LD0LA_1LA1RD j).
    exact (srun_sound tm true true che_0RB1LC_1LC0RD_0LD0LA_1LA1RD BE0_0RB1LC_1LC0RD_0LD0LA_1LA1RD B1_0RB1LC_1LC0RD_0LD0LA_1LA1RD 4 15
             run_exit_0RB1LC_1LC0RD_0LD0LA_1LA1RD [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.



(** ** The lap *)

Lemma lap_0RB1LC_1LC0RD_0LD0LA_1LA1RD : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_0RB1LC_1LC0RD_0LD0LA_1LA1RD p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_0RB1LC_1LC0RD_0LD0LA_1LA1RD p j' E).
Qed.

(** ** Bootstrap *)

Lemma boot_0RB1LC_1LC0RD_0LD0LA_1LA1RD : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 12.
  assert (H : match csteps tm 12 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 12 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_0RB1LC_1LC0RD_0LD0LA_1LA1RD : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_0RB1LC_1LC0RD_0LD0LA_1LA1RD = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_0RB1LC_1LC0RD_0LD0LA_1LA1RD p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_0RB1LC_1LC0RD_0LD0LA_1LA1RD p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_0RB1LC_1LC0RD_0LD0LA_1LA1RD : forall t, ~ In t pins_0RB1LC_1LC0RD_0LD0LA_1LA1RD ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n c', 0 < n /\ csteps tm n (Cc p0) = Some c'
                         /\ lift c' = lift (Cc (Pos.succ p0)))
    by exact lapi_0RB1LC_1LC0RD_0LD0LA_1LA1RD.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StA, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB1LC_1LC0RD_0LD0LA_1LA1RD [SWinR 2] (StA, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* A1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StA, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB1LC_1LC0RD_0LD0LA_1LA1RD [SWinR 6; SRotL 1; SWin 1; SCycL 2 0; SWin 3] (StA, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StB, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB1LC_1LC0RD_0LD0LA_1LA1RD [SWinR 6; SRotL 1; SWin 1; SCycL 2 0; SWin 4; SCycR 2; SWin 2] (StB, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StB, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
