(** ** Bootstrap *)

Lemma boot_0RB1LC_1LC0RD_1LA0LA_1LA1RD : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 8.
  assert (H : match csteps tm 8 c0 with
