Lemma geo_0RB1LC_1LC0RD_1LA0LC_1RB0LC : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_0RB1LC_1LC0RD_1LA0LC_1RB0LC) = lift (Cc (Pos.succ p)).
