(** ** The lap *)

Lemma lap_0RB1LC_1LC0RD_1LA0LC_1RB0LC : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
