  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_0RB1LC_1LC0RD_1LA0LC_1RB0LC p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_0RB1LC_1LC0RD_1LA0LC_1RB0LC B0_0RB1LC_1LC0RD_1LA0LC_1RB0LC B1_0RB1LC_1LC0RD_1LA0LC_1RB0LC 4 10 p j' [] []).
    + exact run_ovf_0RB1LC_1LC0RD_1LA0LC_1RB0LC.
    + reflexivity.
    + reflexivity.
    + exact (gso_0RB1LC_1LC0RD_1LA0LC_1RB0LC p j' E).
    + exact (geo_0RB1LC_1LC0RD_1LA0LC_1RB0LC p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma boot_0RB1LC_1LC0RD_1LA0LC_1RB0LC : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
