(** ** The lap *)

Lemma lap_0RB1LC_1LC1RB_0LD1LD_0RA0LC : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
