    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_0RB1LC_1LC1RB_0LD1LD_0RA0LC p j' E).
Qed.

(** ** Bootstrap *)

Lemma boot_0RB1LC_1LC1RB_0LD1LD_0RA0LC : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
