(** ** The lap *)

Lemma lap_0RB1LC_1RC0RC_1LD1RB_1LA0LD : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_0RB1LC_1RC0RC_1LD1RB_1LA0LD p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_0RB1LC_1RC0RC_1LD1RB_1LA0LD B0_0RB1LC_1RC0RC_1LD1RB_1LA0LD B1_0RB1LC_1RC0RC_1LD1RB_1LA0LD 4 20 p j' [] []).
    + exact run_ovf_0RB1LC_1RC0RC_1LD1RB_1LA0LD.
    + reflexivity.
    + reflexivity.
    + exact (gso_0RB1LC_1RC0RC_1LD1RB_1LA0LD p j' E).
    + exact (geo_0RB1LC_1RC0RC_1LD1RB_1LA0LD p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma boot_0RB1LC_1RC0RC_1LD1RB_1LA0LD : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 25.
  assert (H : match csteps tm 25 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 25 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_0RB1LC_1RC0RC_1LD1RB_1LA0LD : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_0RB1LC_1RC0RC_1LD1RB_1LA0LD = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_0RB1LC_1RC0RC_1LD1RB_1LA0LD p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_0RB1LC_1RC0RC_1LD1RB_1LA0LD p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_0RB1LC_1RC0RC_1LD1RB_1LA0LD : forall t, ~ In t pins_0RB1LC_1RC0RC_1LD1RB_1LA0LD ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
