(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_0RB1LD_0RC1LB_1LA1RC_0LB0LA : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] j A0_0RB1LD_0RC1LB_1LA1RC_0LB0LA.
