Lemma gen_0RB1LD_0RC1LD_1LA1RC_0RC0LB : forall v i q0, cview v = (i, Some q0) ->
  lift (cden (Ip q0 ++ [S1]) [] i AI1_0RB1LD_0RC1LD_1LA1RC_0RC0LB) = lift (Cin (Pos.succ v)).
