    apply (lap_of_run tm Cc true true cho_0RB1LD_0RC1RB_1LB1LD_1LA0LA B0_0RB1LD_0RC1RB_1LB1LD_1LA0LA B1_0RB1LD_0RC1RB_1LB1LD_1LA0LA 4 10 p j' [] []).
