(** ** Bootstrap *)

Lemma boot_0RB1LD_1LA1RC_0LA1RB_0LA0RA : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 6.
  assert (H : match csteps tm 6 c0 with
