    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_0RB1LD_1LA1RC_0LA1RB_1RB0LA p j' E).
Qed.

(** ** Bootstrap *)

Lemma boot_0RB1LD_1LA1RC_0LA1RB_1RB0LA : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
