    anchor by boot + the inner counter's own laps + that prefix. *)
Lemma firex_0RB1LD_1LA1RC_0LA1RB_1RB0LA : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l BE0_0RB1LD_1LA1RC_0LA1RB_1RB0LA = Some t ->
