             run_boot_0RB1LD_1LA1RC_0LA1RB_1RB0LA [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - apply (fire_lift_of_csteps tm (fun _ : positive => Cin (fill (pow2 j))) xH).
    apply (fire_of_run_instr tm (fun _ : positive => Cin (fill (pow2 j)))
                      true true l BE0_0RB1LD_1LA1RC_0LA1RB_1RB0LA xH j [] []);
